    "c3_choice_detour": {
      "choices": [
        {
          "id": "c3_dt_coast",
          "label": "走东岬：今晚绕一段海堤，明早再上坡。",
          "next": "c3_co01",
          "reaction": "伊芙娜把地图折起来收进口袋。她说沿海堤走到检修道就回船，车留在堤口；明早接上诺瓦，再一起去台地。",
          "effects": [
            {
              "type": "flag",
              "key": "c3_dt_coast",
              "value": true
            }
          ]
        },
        {
          "id": "c3_dt_direct",
          "label": "海堤先不去，明天七个小时都留给台地。",
          "next": "c3_dt_d1",
          "reaction": "伊芙娜在台地那条线上按了一下：「好，明天专跑这一趟。风暴过去，路基得断一半，要查的都查完再下来。」",
          "effects": [
            {
              "type": "flag",
              "key": "c3_dt_direct",
              "value": true
            }
          ]
        }
      ]
    },
    "c3_lb02": {
      "text": "伊芙娜拉开车门：「灰鸢、夜枭，从台地直接起飞。母舰在浅海外面，无人机正抢北侧三座基站。」\n「那是这一带唯一的高点。让它们拿到，整个澜湾的锚点都会被接成中继站。」"
    },
    "c3_lb03": {
      "text": "「港区建筑禁射。看清目标再开火，追到浅海线就停，外海有敌方母舰火力。」\n伊芙娜拉上车门：「我守坡下的短波中继，你领两机打。频道一直开着。」"
    },
    "c3_lb05": {
      "text": "「第一组六个，高一百二，速度七十。北偏东十七度！」\n薇拉盯住前排：「全朝基站去了。那点载荷穿不透混凝土——它们盯的是天线。」"
    },
    "c3_lb09": {
      "text": "「第二组八个，两段式！前段打天线，后段扑关节。」\n薇拉转动探测头：「引信认金属。我得收住右侧探测臂，从侧面给你报距离。」"
    },
    "c3_lb10": {
      "text": "「西侧，又来了！」薇拉喘了一口气，「第三组九台，贴水面，正转港区。车队就在前面！」"
    },
    "c3_lb11": {
      "text": "伊芙娜的短波切进来：「车队过西侧堤口还要八分钟。渡鸦号在锚地，这里开不了火。」\n「港务派了两条渔政艇，火力顶不住。灰鸢、夜枭，接住这一波。」"
    },
    "c3_lb13": {
      "text": "「夜枭，三百米，红外已开。浮体七个，水下还有两个。」\n薇拉把位置送进渔政艇频道：「第一艘注意右舷，七十米，有东西在动！往那边压会撞上。」"
    },
    "c3_lb15": {
      "text": "「左膝外侧磕破了，我自己的。」薇拉吸了口气。刚才急横切，座舱手肘护板甩到最外侧，她的膝盖碰上操纵台下的横梁。\n「脚踏还能踩，我继续报。」夜枭稳住高度，探测臂仍追着水线。"
    },
    "c3_lb16": {
      "text": "「车队过堤口了。灰鸢撤出浪线，夜枭接一下！」伊芙娜的声音盖过电流声，「残敌交渔政艇。大浮体打不动，先拖住。」"
    },
    "c3_lb18": {
      "text": "「夜枭接口箱有划痕，还能用。」薇拉切到灰鸢的读数，「你的右腿液压低了百分之十四。得收了，再打撑不住。」"
    },
    "c3_sb02": {
      "text": "「西口还有十七条撤离船，最大那条载了四十六人。」伊芙娜的短波混着浪声，「渡鸦号近防炮只能护水道，西口够不到。你们两台过去，把船接进来！」"
    },
    "c3_sb03": {
      "text": "「水深二十三米，浮体吃水九米，能逼上浅堆。」薇拉飞快报完，「现在风浪九级，低过三十米就会被浪遮住。得留一台在高处看。」"
    },
    "c3_sb05": {
      "text": "「等一下，灰鸢右腿液压还低百分之十四！」薇拉抢进频道，「掠海那段要单腿承重。夜枭推力小些，右腿是好的，低处我来更稳。」"
    },
    "c3_sb_a2": {
      "text": "「第一艘停火。第二艘正往浅堆冲！」薇拉在浪声里喊，「它还想搁住当炮台。推回深水，还是让它上去？」"
    },
    "c3_sb_b2": {
      "text": "「灰鸢右腿漏油了。现在还能飞，落地时那条腿会软。」\n薇拉连着报出两处：「堤口西侧二十米，硬岩；东侧四十米，湿沙。沙会陷，岩面会滑，选一个，我盯着。」"
    },
    "c3_sb_b4": {
      "text": "灰鸢落在堤口东侧四十米外的湿沙上，右腿陷进去，机身整个往右歪。你用左臂撑住地面，把机身扶正，浪从背后推上来，埋过膝盖，又退回去。"
    },
    "c3_sb_c1": {
      "text": "两台机体同时压进浪线。灰鸢在第一艘浮体上打开一个口子；夜枭绕到第二艘侧后，用左机械手扣住转向桨，将它扳离轴座。\n两机交错时，那只机械手从灰鸢右肩甲上方擦过，相隔不到一米。"
    },
    "c3_sb_c2": {
      "text": "「你右肩上方，一米。」薇拉的报位紧跟着手臂动作，「保持，我能过去。」\n探测臂盯着灰鸢机背，直到两机错开。"
    },
    "c3_sb07": {
      "text": "「两台都回港区。」伊芙娜说，「你陪薇拉去医务舱，让军医看看左膝。现在就去。」"
    },
    "c3_rp02": {
      "text": "铎兰端来一锅面，盖上压着赭红布巾：「昨天的汤，刚下的面。碗拿来，捞慢了全黏一块。」\n他将锅放上机库的折叠桌：「晚班的也留了，回来去灶上热。锅别再烧干，我可刚刷完。」"
    },
    "c3_rp04": {
      "text": "「停，第三遍了，再倒就只能兑水。」诺瓦伸手去拿盐罐，「给我吧。」\n薇拉尝了一小口：「这回刚好。」她将杯子往桌子中间推了半寸，招呼你们也尝尝。"
    },
    "c3_q107": {
      "text": "「不用拦，他迟早会来核。」薇拉把灯调暗，手停在开关上。\n「你留一会儿吧。我现在想有人陪着。」"
    },
    "c3_q109": {
      "text": "薇拉望着桌沿：「你小时候，有没有谁送过一样东西，喜欢得一直留着？有人来要，也舍不得还。」"
    },
    "c3_q111": {
      "text": "「都穿破了，还留着。」薇拉低头摸到颈绳上的秒表，「这只是我原来带的，没刻字，一直停在零位。」\n她用掌心拢住表壳：「为什么到我这里，我还不知道。可我想一直带着。」"
    },
    "c3_lb14": {
      "text": "灰鸢落在西侧堤口外沿的湿沙上，脚下立刻陷进去半米。堤面上，车队的头灯一串一串地往东移，尾车还在浪线后面。"
    },
    "c3_lb14_b": {
      "text": "沙和水还在脚边翻涌，第一台无人机已从浪线后冲出来，速度七十，高度不到二十米，直扑车队的尾车。你横着撞过去，把它按进浅水；第二台从侧面咬上来，碎片打在胸甲上，声音很闷。"
    },
    "c3_q101_b": {
      "text": "船上的夜班接着清点货舱、查过夜机位，舰桥仍每两小时记一次航况。伊芙娜在战斗记录末尾补上：灰鸢右腿液压管已更换，夜枭接口箱检查正常；人员一处擦伤，已处理。她合上夹板，将笔放回槽里。"
    },
