          "next": "c3_nm_d1",
          "reaction": "三份纸留在战术台中间，一只磁扣压着三个角。基廷看了两秒，把文件夹扣上；铎兰把货价表折回原来的折痕；诺瓦往观测局的频道发了一行回执，写着暂缓。",
