          "reaction": "定时器拆下来，触点果然烧了一个小坑。刮干净，剪一条薄垫片垫上，第四档的指针就不抖了。\n加热台重新亮起来的时候，蹲在门边的两个坞架工回头看了一眼，又把头转回去了。",
